import type { ButtonHTMLAttributes, ReactNode } from "react";
import { cx } from "../lib/cx";
import { Icon, type IconName } from "./Icon";
import styles from "./Button.module.css";

type Variant = "tonal" | "filled" | "outline" | "text" | "inverse";

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  icon?: IconName;
  size?: "s" | "m";
  children?: ReactNode;
}

export function Button({ variant = "tonal", icon, size = "m", className, children, type = "button", ...rest }: ButtonProps) {
  return (
    <button type={type} className={cx(styles.button, styles[variant], styles[size], !children && styles.iconOnly, className)} {...rest}>
      {icon && <Icon name={icon} size={size === "s" ? 18 : 24} />}
      {children && <span className={styles.label}>{children}</span>}
    </button>
  );
}

export function IconButton({ icon, label, className, size = 40, ...rest }: { icon: IconName; label: string; size?: number } & ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button type="button" className={cx(styles.iconButton, className)} aria-label={label} title={label} style={{ width: size, height: size }} {...rest}>
      <Icon name={icon} size={Math.min(24, size - 12)} />
    </button>
  );
}
