import { Link } from "react-router";
import type { ChannelSummary } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { Button } from "../../components/Button";
import { ChannelName, channelPath } from "../../components/ChannelName";
import { SubscribeButton } from "../../components/SubscribeButton";
import { formatSubscribers } from "../../lib/format";
import styles from "./VideoOwner.module.css";

export function VideoOwner({ channel }: { channel: ChannelSummary }) {
  return (
    <div className={styles.owner} data-owner="">
      <Link to={channelPath(channel)} aria-label={channel.name} tabIndex={-1}>
        <Avatar src={channel.avatar} size={40} />
      </Link>
      <div className={styles.text}>
        <ChannelName channel={channel} surface="watch-owner" className={styles.name} />
        <span className={styles.subscribers}>{formatSubscribers(channel.subscriberCount)}</span>
      </div>
      <Button variant="outline">Join</Button>
      <SubscribeButton channelId={channel.id} channelName={channel.name} />
    </div>
  );
}
