import { infiniteQueryOptions, queryOptions } from "@tanstack/react-query";
import { apiGet } from "./client";
import type { ChannelResponse, ChannelVideoSort, ChannelVideosPage, CommentSort, CommentsPage, HomeResponse, SearchPage, SuggestResponse, WatchResponse } from "./types";

const enc = encodeURIComponent;
const nextPage = (last: { nextPage: number | null }) => last.nextPage ?? undefined;

export const homeQuery = () => queryOptions({ queryKey: ["home"], queryFn: () => apiGet<HomeResponse>("home") });

export const suggestQuery = (query: string) =>
  queryOptions({
    queryKey: ["suggest", query],
    queryFn: () => apiGet<SuggestResponse>(`suggest?q=${enc(query)}`),
    enabled: query.length > 0,
    staleTime: Infinity,
  });

export const searchQuery = (query: string) =>
  infiniteQueryOptions({
    queryKey: ["search", query],
    queryFn: ({ pageParam }) => apiGet<SearchPage>(`search?q=${enc(query)}&page=${pageParam}`),
    initialPageParam: 0,
    getNextPageParam: nextPage,
  });

export const watchQuery = (videoId: string) => queryOptions({ queryKey: ["watch", videoId], queryFn: () => apiGet<WatchResponse>(`videos/${enc(videoId)}`) });

export const commentsQuery = (videoId: string, sort: CommentSort) =>
  infiniteQueryOptions({
    queryKey: ["comments", videoId, sort],
    queryFn: ({ pageParam }) => apiGet<CommentsPage>(`videos/${enc(videoId)}/comments?sort=${sort}&page=${pageParam}`),
    initialPageParam: 0,
    getNextPageParam: nextPage,
  });

export const channelQuery = (handle: string) => queryOptions({ queryKey: ["channel", handle], queryFn: () => apiGet<ChannelResponse>(`channels/@${enc(handle)}`) });

export const channelVideosQuery = (handle: string, sort: ChannelVideoSort) =>
  infiniteQueryOptions({
    queryKey: ["channel-videos", handle, sort],
    queryFn: ({ pageParam }) => apiGet<ChannelVideosPage>(`channels/@${enc(handle)}/videos?sort=${sort}&page=${pageParam}`),
    initialPageParam: 0,
    getNextPageParam: nextPage,
  });
