import { useQuery } from "@tanstack/react-query";
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate, useSearchParams } from "react-router";
import { suggestQuery } from "../../api/queries";
import { Icon } from "../../components/Icon";
import { cx } from "../../lib/cx";
import { useDebouncedCallback } from "../../lib/debounce";
import { highlight } from "../../lib/richText";
import { log } from "../../lib/telemetry";
import { emit } from "../../lib/workload";
import styles from "./SearchBox.module.css";

export function SearchBox() {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const [value, setValue] = useState(params.get("search_query") ?? "");
  const [term, setTerm] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const updateTerm = useDebouncedCallback((next: string) => setTerm(next.trim()), 150);
  const { data } = useQuery({ ...suggestQuery(term), enabled: open && term.length > 0 });
  const suggestions = open && data && data.query === term ? data.suggestions : [];

  const search = (query: string, source: "submit" | "suggestion") => {
    const trimmed = query.trim();
    if (!trimmed) return;
    setValue(trimmed);
    setOpen(false);
    setActive(-1);
    log({ type: "search", query: trimmed, source });
    navigate(`/results?search_query=${encodeURIComponent(trimmed)}`);
  };

  const onSubmit = (event: FormEvent) => {
    event.preventDefault();
    search(active >= 0 ? suggestions[active] : value, active >= 0 ? "suggestion" : "submit");
  };

  return (
    <form className={styles.form} role="search" onSubmit={onSubmit} action="results">
      <div className={cx(styles.field, open && suggestions.length > 0 && styles.expanded)}>
        <input
          className={styles.input}
          name="search_query"
          type="text"
          placeholder="Search"
          autoComplete="off"
          aria-label="Search"
          role="combobox"
          aria-expanded={suggestions.length > 0}
          aria-controls="search-suggestions"
          aria-activedescendant={active >= 0 ? `suggestion-${active}` : undefined}
          value={value}
          onChange={(event) => {
            setValue(event.target.value);
            setOpen(true);
            setActive(-1);
            updateTerm(event.target.value);
          }}
          onKeyDown={(event) => {
            if (event.key === "ArrowDown") setActive((i) => Math.min(suggestions.length - 1, i + 1));
            else if (event.key === "ArrowUp") setActive((i) => Math.max(-1, i - 1));
            else if (event.key === "Escape") setOpen(false);
          }}
          onBlur={() => setOpen(false)}
        />
        {value && (
          <button type="button" className={styles.clear} aria-label="Clear search query" onClick={() => setValue("")}>
            ×
          </button>
        )}
        {suggestions.length > 0 && <Suggestions query={term} suggestions={suggestions} active={active} onPick={(s) => search(s, "suggestion")} />}
      </div>
      <button type="submit" className={styles.submit} aria-label="Search" data-search-submit="">
        <Icon name="search" />
      </button>
    </form>
  );
}

function Suggestions({ query, suggestions, active, onPick }: { query: string; suggestions: string[]; active: number; onPick: (suggestion: string) => void }) {
  useEffect(() => {
    log({ type: "suggestions_shown", query, count: suggestions.length });
    emit("suggestions-rendered", { query, count: suggestions.length });
  }, [query, suggestions]);
  return (
    <ul className={styles.suggestions} id="search-suggestions" role="listbox" aria-label="Suggestions">
      {suggestions.map((suggestion, i) => (
        <li
          key={suggestion}
          id={`suggestion-${i}`}
          role="option"
          aria-selected={i === active}
          className={cx(styles.suggestion, i === active && styles.active)}
          onPointerDown={(event) => event.preventDefault()}
          onClick={() => onPick(suggestion)}
        >
          <Icon name="search" size={18} className={styles.suggestionIcon} />
          <span>
            {highlight(suggestion, query).map((part, j) => (part.match ? <span key={j}>{part.text}</span> : <b key={j}>{part.text}</b>))}
          </span>
        </li>
      ))}
    </ul>
  );
}
