import { Fragment } from "react";
import { Link } from "react-router";
import { parseText } from "../lib/richText";
import styles from "./RichText.module.css";

/** User text with its links, hashtags, mentions and seekable timestamps. */
export function RichText({ text, onSeek }: { text: string; onSeek?: (seconds: number) => void }) {
  const lines = parseText(text);
  return (
    <>
      {lines.map((segments, line) => (
        <Fragment key={line}>
          {line > 0 && <br />}
          {segments.map((segment, i) => {
            switch (segment.type) {
              case "text":
                return <Fragment key={i}>{segment.text}</Fragment>;
              case "url":
                return (
                  <a key={i} className={styles.link} href={segment.href} target="_blank" rel="noopener noreferrer nofollow">
                    {segment.text}
                  </a>
                );
              case "hashtag":
                return (
                  <Link key={i} className={styles.link} to={`/results?search_query=${encodeURIComponent(segment.text)}`}>
                    {segment.text}
                  </Link>
                );
              case "mention":
                return (
                  <Link key={i} className={styles.mention} to={`/@${segment.handle}/videos`}>
                    {segment.text}
                  </Link>
                );
              case "timestamp":
                return (
                  <button key={i} type="button" className={styles.timestamp} onClick={() => onSeek?.(segment.seconds)} aria-label={`Jump to ${segment.text}`}>
                    {segment.text}
                  </button>
                );
            }
          })}
        </Fragment>
      ))}
    </>
  );
}
