import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { useSearchParams } from "react-router";
import { watchQuery } from "../../api/queries";
import { useDocumentTitle } from "../../lib/hooks";
import { navigationDuration } from "../../lib/navigation";
import { flush, log } from "../../lib/telemetry";
import { emit } from "../../lib/workload";
import { CompanionAd } from "../ads/CompanionAd";
import { CommentsSection } from "../comments/CommentsSection";
import { Description } from "./Description";
import { Player } from "./Player";
import { RelatedList } from "./RelatedList";
import { VideoActions } from "./VideoActions";
import { VideoOwner } from "./VideoOwner";
import styles from "./WatchPage.module.css";

function startTime(value: string | null): number {
  const match = value?.match(/^(\d+)s?$/);
  return match ? Number(match[1]) : 0;
}

export function WatchPage() {
  const [params] = useSearchParams();
  const videoId = params.get("v") ?? "";
  const { data } = useQuery(watchQuery(videoId));
  // The router renders a page only once its loader has the data.
  const { video, related, relatedChips, companionAd } = data!;
  const [time, setTime] = useState(() => startTime(params.get("t")));
  useDocumentTitle(video.title);

  useEffect(() => {
    log({ type: "page_view", page: "watch", path: `/watch?v=${videoId}`, durationMs: navigationDuration() });
    flush();
    emit("page-rendered", { page: "watch", videoId });
  }, [videoId]);

  const seek = (seconds: number) => {
    setTime(seconds);
    window.scrollTo(0, 0);
    log({ type: "interaction", name: "seek", detail: String(seconds) });
  };

  return (
    <div className={styles.page} data-page="watch">
      <div className={styles.primary}>
        <Player video={video} time={time} onSeek={seek} />
        <h1 className={styles.title}>{video.title}</h1>
        <div className={styles.topRow}>
          <VideoOwner channel={video.channel} />
          <VideoActions video={video} />
        </div>
        <Description key={video.id} video={video} onSeek={seek} />
        <CommentsSection key={`comments-${video.id}`} videoId={video.id} commentCount={video.commentCount} channelHandle={video.channel.handle} onSeek={seek} />
      </div>
      <div className={styles.secondary}>
        {companionAd && <CompanionAd ad={companionAd} />}
        <RelatedList videos={related} chips={relatedChips} channelId={video.channel.id} />
      </div>
    </div>
  );
}
