// The frozen clock: "now" is the page config's date, so that relative dates
// read the same in every run.
let now = 0;

export function setNow(iso: string) {
  now = Date.parse(iso);
}

export function nowMs(): number {
  return now;
}

export function nowIso(): string {
  return new Date(now).toISOString();
}
