import { nowMs } from "./clock";

const LOCALE = "en-US";
const compact = new Intl.NumberFormat(LOCALE, { notation: "compact", maximumFractionDigits: 1 });
const full = new Intl.NumberFormat(LOCALE);
const relative = new Intl.RelativeTimeFormat(LOCALE, { numeric: "always" });
const date = new Intl.DateTimeFormat(LOCALE, { dateStyle: "medium", timeZone: "UTC" });
const hours = new Intl.NumberFormat(LOCALE, { style: "unit", unit: "hour", unitDisplay: "long" });
const minutes = new Intl.NumberFormat(LOCALE, { style: "unit", unit: "minute", unitDisplay: "long" });
const seconds = new Intl.NumberFormat(LOCALE, { style: "unit", unit: "second", unitDisplay: "long" });
const plural = new Intl.PluralRules(LOCALE);

export function formatCompact(value: number): string {
  return compact.format(value);
}

export function formatCount(value: number): string {
  return full.format(value);
}

/** "1 view", "12K views", or "No views". */
export function formatViews(value: number, long = false): string {
  if (value === 0) return "No views";
  const number = long ? full.format(value) : compact.format(value);
  return `${number} ${plural.select(value) === "one" ? "view" : "views"}`;
}

export function formatWatching(value: number): string {
  return `${compact.format(value)} watching`;
}

export function formatSubscribers(value: number): string {
  return `${compact.format(value)} ${plural.select(value) === "one" ? "subscriber" : "subscribers"}`;
}

export function pluralize(value: number, one: string, other: string, formatted = full.format(value)): string {
  return `${formatted} ${plural.select(value) === "one" ? one : other}`;
}

const UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 365 * 86400],
  ["month", 30 * 86400],
  ["week", 7 * 86400],
  ["day", 86400],
  ["hour", 3600],
  ["minute", 60],
  ["second", 1],
];

/** "3 weeks ago", relative to the frozen now. */
export function formatRelative(iso: string): string {
  const elapsed = Math.max(0, (nowMs() - Date.parse(iso)) / 1000);
  for (const [unit, size] of UNITS) {
    if (elapsed >= size || unit === "second") return relative.format(-Math.floor(elapsed / size), unit);
  }
  return "";
}

export function isRecent(iso: string, days = 7): boolean {
  return nowMs() - Date.parse(iso) < days * 86400000;
}

export function formatDate(iso: string): string {
  return date.format(Date.parse(iso));
}

/** "47:23" or "1:02:03". */
export function formatDuration(total: number): string {
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = String(Math.floor(total % 60)).padStart(2, "0");
  return h ? `${h}:${String(m).padStart(2, "0")}:${s}` : `${m}:${s}`;
}

/** "1 hour, 2 minutes, 3 seconds", for screen readers. */
export function durationLabel(total: number): string {
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = Math.floor(total % 60);
  const parts: string[] = [];
  if (h) parts.push(hours.format(h));
  if (m) parts.push(minutes.format(m));
  if (s || !parts.length) parts.push(seconds.format(s));
  return parts.join(", ");
}

/** Parses "1:02:03" or "2:31" into seconds. */
export function parseTimestamp(text: string): number {
  return text.split(":").reduce((total, part) => total * 60 + Number(part), 0);
}
