import { Link } from "react-router";
import type { ChannelRef } from "../api/types";
import { cx } from "../lib/cx";
import { logClick } from "../lib/telemetry";
import { Icon } from "./Icon";
import styles from "./ChannelName.module.css";

export function channelPath(channel: { handle: string }, tab = "videos") {
  return `/@${channel.handle}/${tab}`;
}

/** A channel's name, linked, with the verified check and its tooltip. */
export function ChannelName({ channel, surface, className, link = true }: { channel: ChannelRef; surface: string; className?: string; link?: boolean }) {
  const content = (
    <>
      <span className={styles.name}>{channel.name}</span>
      {channel.verified && (
        <span className={styles.verified} title="Verified">
          <Icon name="check" size={14} label="Verified" />
        </span>
      )}
    </>
  );
  if (!link) return <span className={cx(styles.channel, className)}>{content}</span>;
  return (
    <Link to={channelPath(channel)} className={cx(styles.channel, className)} onClick={() => logClick(surface, "channel", channel.id)} data-channel-link="">
      {content}
    </Link>
  );
}
