import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { cx } from "../lib/cx";
import styles from "./Menu.module.css";

export interface MenuItem<T extends string> {
  value: T;
  label: string;
  description?: string;
}

/** A button that opens a list of choices below it. */
export function Menu<T extends string>({ trigger, items, selected, onSelect, label, align = "start" }: { trigger: (props: { open: boolean; toggle: () => void; id: string }) => ReactNode; items: MenuItem<T>[]; selected?: T; onSelect: (value: T) => void; label: string; align?: "start" | "end" }) {
  const [open, setOpen] = useState(false);
  const id = useId();
  const root = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const close = (event: Event) => {
      if (!root.current?.contains(event.target as Node)) setOpen(false);
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", escape);
    };
  }, [open]);

  return (
    <div className={styles.root} ref={root}>
      {trigger({ open, toggle: () => setOpen((value) => !value), id })}
      {open && (
        <ul className={cx(styles.menu, align === "end" && styles.end)} role="menu" id={id} aria-label={label}>
          {items.map((item) => (
            <li key={item.value} role="none">
              <button
                type="button"
                role="menuitemradio"
                aria-checked={item.value === selected}
                className={cx(styles.item, item.value === selected && styles.selected)}
                onClick={() => {
                  setOpen(false);
                  onSelect(item.value);
                }}
                data-menu-value={item.value}
              >
                <span>{item.label}</span>
                {item.description && <span className={styles.description}>{item.description}</span>}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
