import { useState } from "react";
import { log } from "../lib/telemetry";
import { Button } from "./Button";

export function SubscribeButton({ channelId, channelName }: { channelId: string; channelName: string }) {
  const [subscribed, setSubscribed] = useState(false);
  return (
    <Button
      variant={subscribed ? "tonal" : "filled"}
      icon={subscribed ? "bell" : undefined}
      aria-pressed={subscribed}
      aria-label={subscribed ? `Unsubscribe from ${channelName}` : `Subscribe to ${channelName}`}
      onClick={() => {
        setSubscribed(!subscribed);
        log({ type: "interaction", name: subscribed ? "unsubscribe" : "subscribe", detail: channelId });
      }}
    >
      {subscribed ? "Subscribed" : "Subscribe"}
    </Button>
  );
}
