import { Link } from "react-router";
import type { VideoSummary } from "../../api/types";
import { Badges } from "../../components/Badges";
import { IconButton } from "../../components/Button";
import { ChannelName } from "../../components/ChannelName";
import { Thumbnail } from "../../components/Thumbnail";
import { VideoMeta } from "../../components/VideoMeta";
import { logClick, useImpression } from "../../lib/telemetry";
import { videoLabel, videoPath } from "../search/VideoResult";
import styles from "./CompactVideo.module.css";

/** A related video in the watch page's side column. */
export function CompactVideo({ video, position }: { video: VideoSummary; position: number }) {
  useImpression("watch-related", "video", video.id, position);
  const onClick = () => logClick("watch-related", "video", video.id, position);
  return (
    <article className={styles.item} data-related="">
      <Link to={videoPath(video.id)} className={styles.thumbnail} onClick={onClick} tabIndex={-1} aria-hidden="true">
        <Thumbnail video={video} width={168} size="s" />
      </Link>
      <div className={styles.details}>
        <h3 className={styles.title}>
          <Link to={videoPath(video.id)} onClick={onClick} aria-label={videoLabel(video)} title={video.title}>
            {video.title}
          </Link>
        </h3>
        <ChannelName channel={video.channel} surface="watch-related" className={styles.channel} />
        <VideoMeta video={video} />
        <Badges video={video} max={2} />
      </div>
      <IconButton icon="more" label="Action menu" size={36} className={styles.menu} />
    </article>
  );
}
