import { useState } from "react";
import type { VideoSummary } from "../../api/types";
import { ChipBar } from "../../components/ChipBar";
import { CompactVideo } from "./CompactVideo";
import styles from "./RelatedList.module.css";

export function RelatedList({ videos, chips, channelId }: { videos: VideoSummary[]; chips: string[]; channelId: string }) {
  const [filter, setFilter] = useState("0");
  const shown = filter === "1" ? videos.filter((video) => video.channel.id === channelId) : videos;
  return (
    <section className={styles.related} aria-label="Related videos">
      <ChipBar chips={chips.map((label, i) => ({ id: String(i), label }))} selected={filter} onSelect={setFilter} label="Related filters" />
      <div className={styles.list}>
        {shown.map((video, i) => (
          <CompactVideo key={video.id} video={video} position={i} />
        ))}
      </div>
    </section>
  );
}
