import { useRef, useState } from "react";
import type { VideoDetail } from "../../api/types";
import { RichText } from "../../components/RichText";
import { cx } from "../../lib/cx";
import { formatDate, formatRelative, formatViews } from "../../lib/format";
import { useIsTruncated } from "../../lib/hooks";
import { log } from "../../lib/telemetry";
import styles from "./Description.module.css";

/** The description box: collapsed to a few lines, with "...more" when the text doesn't fit. */
export function Description({ video, onSeek }: { video: VideoDetail; onSeek: (seconds: number) => void }) {
  const [expanded, setExpanded] = useState(false);
  const body = useRef<HTMLDivElement>(null);
  const truncated = useIsTruncated(body, [video.id]);
  const hashtags = video.description.split("\n")[0].split(" ").filter((word) => word.startsWith("#"));
  const expand = () => {
    if (expanded) return;
    setExpanded(true);
    log({ type: "interaction", name: "expand_description", detail: video.id });
  };

  return (
    <section className={cx(styles.box, !expanded && styles.collapsed)} onClick={expand} aria-label="Description">
      <p className={styles.info}>
        <span>{formatViews(video.viewCount, expanded)}</span>
        <span>{expanded ? `Premiered ${formatDate(video.publishedAt)}` : formatRelative(video.publishedAt)}</span>
        {hashtags.slice(0, 3).map((tag) => (
          <span key={tag} className={styles.tag}>
            {tag}
          </span>
        ))}
      </p>
      <div ref={body} className={cx(styles.body, !expanded && styles.clamped)}>
        <RichText text={video.description.split("\n").slice(2).join("\n")} onSeek={onSeek} />
      </div>
      {expanded && (
        <dl className={styles.facts}>
          <div>
            <dt>Category</dt>
            <dd>{video.category}</dd>
          </div>
          <div>
            <dt>License</dt>
            <dd>{video.license}</dd>
          </div>
          <div>
            <dt>Tags</dt>
            <dd>{video.tags.join(", ")}</dd>
          </div>
        </dl>
      )}
      {!expanded && truncated && (
        <button type="button" className={styles.more} onClick={expand} data-description-more="">
          ...more
        </button>
      )}
      {expanded && (
        <button
          type="button"
          className={styles.less}
          onClick={(event) => {
            event.stopPropagation();
            setExpanded(false);
          }}
        >
          Show less
        </button>
      )}
    </section>
  );
}
