import { Link } from "react-router";
import type { SearchVideo } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { Badges } from "../../components/Badges";
import { IconButton } from "../../components/Button";
import { ChannelName, channelPath } from "../../components/ChannelName";
import { Thumbnail } from "../../components/Thumbnail";
import { VideoMeta } from "../../components/VideoMeta";
import { durationLabel, formatRelative, formatViews, pluralize } from "../../lib/format";
import { highlight } from "../../lib/richText";
import { logClick, useImpression } from "../../lib/telemetry";
import styles from "./VideoResult.module.css";

export function videoPath(id: string) {
  return `/watch?v=${id}`;
}

export function videoLabel(video: SearchVideo | import("../../api/types").VideoSummary): string {
  const parts = [video.title, `by ${video.channel.name}`];
  if (video.live) parts.push("live now");
  else parts.push(formatViews(video.viewCount, true), formatRelative(video.publishedAt), durationLabel(video.durationSeconds));
  return parts.join(" ");
}

export function VideoResult({ video, position, query }: { video: SearchVideo; position: number; query: string }) {
  useImpression("search", "video", video.id, position);
  const onClick = () => logClick("search", "video", video.id, position);
  return (
    <article className={styles.result} data-result="video">
      <Link to={videoPath(video.id)} className={styles.thumbnail} onClick={onClick} tabIndex={-1} aria-hidden="true">
        <Thumbnail video={video} width={360} progress={video.progress} size="l" />
      </Link>
      <div className={styles.details}>
        <div className={styles.titleRow}>
          <h3 className={styles.title}>
            <Link to={videoPath(video.id)} onClick={onClick} aria-label={videoLabel(video)} title={video.title} data-video-link="">
              {video.title}
            </Link>
          </h3>
          <IconButton icon="more" label="Action menu" className={styles.menu} />
        </div>
        <VideoMeta video={video} />
        <div className={styles.channel}>
          <Link to={channelPath(video.channel)} tabIndex={-1} aria-hidden="true">
            <Avatar src={video.channel.avatar} size={24} />
          </Link>
          <ChannelName channel={video.channel} surface="search" />
        </div>
        <p className={styles.snippet}>
          {highlight(video.snippet, query).map((part, i) => (part.match ? <b key={i}>{part.text}</b> : <span key={i}>{part.text}</span>))}
        </p>
        {video.chapterCount > 0 && <p className={styles.chapters}>{pluralize(video.chapterCount, "chapter", "chapters")}</p>}
        <Badges video={video} />
      </div>
    </article>
  );
}
