import { Link } from "react-router";
import type { ChannelSummary } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { ChannelName, channelPath } from "../../components/ChannelName";
import { SubscribeButton } from "../../components/SubscribeButton";
import { formatSubscribers, pluralize } from "../../lib/format";
import { useImpression } from "../../lib/telemetry";
import styles from "./ChannelResult.module.css";

export function ChannelResult({ channel, position }: { channel: ChannelSummary; position: number }) {
  useImpression("search", "channel", channel.id, position);
  return (
    <article className={styles.result} data-result="channel">
      <Link to={channelPath(channel)} className={styles.avatar} aria-label={channel.name}>
        <Avatar src={channel.avatar} size={136} />
      </Link>
      <div className={styles.details}>
        <ChannelName channel={channel} surface="search" className={styles.name} />
        <p className={styles.meta}>
          @{channel.handle} • {formatSubscribers(channel.subscriberCount)} • {pluralize(channel.videoCount, "video", "videos")}
        </p>
        {channel.description && <p className={styles.description}>{channel.description}</p>}
      </div>
      <SubscribeButton channelId={channel.id} channelName={channel.name} />
    </article>
  );
}
