// The simulated network. There is no server: every response of the journey
// is fetched as text before the app starts, and a request is answered in a
// task of its own with a real Response, so the loading state commits first
// and the client still reads and parses the body.
import { afterTask } from "../lib/workload";

const responses = new Map<string, string>();
const sent: { path: string; bytes: number }[] = [];

export async function preloadResponses(base: string) {
  const manifest: Record<string, string> = await (await fetch(`${base}api/manifest.json`)).json();
  await Promise.all(
    Object.entries(manifest).map(async ([path, file]) => {
      responses.set(path, await (await fetch(base + file)).text());
    }),
  );
}

export function request(path: string, init?: { method?: string; body?: string }): Promise<Response> {
  if (init?.method === "POST") {
    sent.push({ path, bytes: init.body?.length ?? 0 });
    return new Promise((resolve) => afterTask(() => resolve(new Response(null, { status: 204 }))));
  }
  const text = responses.get(path);
  return new Promise((resolve) => {
    afterTask(() => {
      resolve(
        text === undefined
          ? new Response(JSON.stringify({ error: "not_found", path }), { status: 404, headers: { "content-type": "application/json" } })
          : new Response(text, { status: 200, headers: { "content-type": "application/json" } }),
      );
    });
  });
}

/** What the app posted (telemetry batches), for inspection. */
export function sentRequests() {
  return sent;
}
