import type { VideoSummary } from "../api/types";
import { isRecent } from "../lib/format";
import { badgeLabel } from "./Thumbnail";
import styles from "./Badges.module.css";

/** The small labels under a video: "New", "4K", "CC", "Live". */
export function Badges({ video, max = 3 }: { video: VideoSummary; max?: number }) {
  const labels: { label: string; tone: "default" | "live" }[] = [];
  if (video.live) labels.push({ label: "Live", tone: "live" });
  else if (isRecent(video.publishedAt)) labels.push({ label: "New", tone: "default" });
  for (const badge of video.badges) {
    if (badge !== "MEMBERS") labels.push({ label: badgeLabel(badge), tone: "default" });
  }
  if (!labels.length) return null;
  return (
    <ul className={styles.badges} aria-label="Badges">
      {labels.slice(0, max).map(({ label, tone }) => (
        <li key={label} className={tone === "live" ? styles.live : styles.badge}>
          {label}
        </li>
      ))}
    </ul>
  );
}
