import { useState } from "react";
import type { VideoDetail } from "../../api/types";
import { IconButton } from "../../components/Button";
import { Icon } from "../../components/Icon";
import { cx } from "../../lib/cx";
import { formatDuration } from "../../lib/format";
import { log } from "../../lib/telemetry";
import styles from "./Player.module.css";

/**
 * The player's chrome around a <video> without media: the poster, the big
 * play button, the progress bar with its chapter segments and the control
 * bar.
 */
export function Player({ video, time, onSeek }: { video: VideoDetail; time: number; onSeek: (seconds: number) => void }) {
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(false);
  const [captions, setCaptions] = useState(false);
  const duration = video.durationSeconds;
  const chapters = video.chapters.length ? video.chapters : [{ startSeconds: 0, title: "" }];
  const current = chapters.findLast((chapter) => chapter.startSeconds <= time) ?? chapters[0];
  const toggle = () => {
    setPlaying(!playing);
    log({ type: "interaction", name: playing ? "pause" : "play", detail: video.id });
  };

  return (
    <div className={cx(styles.player, playing && styles.playing)} data-player="">
      <video className={styles.video} poster={video.thumbnail} preload="none" playsInline aria-label={video.title} />
      {!playing && (
        <button type="button" className={styles.bigPlay} aria-label="Play" onClick={toggle}>
          <svg width="64" height="64" viewBox="0 0 64 64" aria-hidden="true">
            <circle cx="32" cy="32" r="31" fill="rgba(0, 0, 0, 0.55)" stroke="#fff" strokeWidth="2" />
            <path d="M26 20v24l19-12z" fill="#fff" />
          </svg>
        </button>
      )}
      <div className={styles.chrome}>
        <div
          className={styles.progress}
          role="slider"
          tabIndex={0}
          aria-label="Seek slider"
          aria-valuemin={0}
          aria-valuemax={duration}
          aria-valuenow={time}
          aria-valuetext={`${formatDuration(time)} of ${formatDuration(duration)}`}
        >
          {chapters.map((chapter, i) => {
            const end = chapters[i + 1]?.startSeconds ?? duration;
            const width = ((end - chapter.startSeconds) / Math.max(1, duration)) * 100;
            const played = Math.min(1, Math.max(0, (time - chapter.startSeconds) / Math.max(1, end - chapter.startSeconds)));
            return (
              <div key={chapter.startSeconds} className={styles.segment} style={{ width: `${width}%` }} title={chapter.title} onClick={() => onSeek(chapter.startSeconds)}>
                <div className={styles.played} style={{ transform: `scaleX(${played})` }} />
              </div>
            );
          })}
        </div>
        <div className={styles.controls}>
          <div className={styles.left}>
            <IconButton icon={playing ? "pause" : "play"} label={playing ? "Pause (k)" : "Play (k)"} onClick={toggle} className={styles.control} size={48} />
            <IconButton icon="next" label="Next (SHIFT+n)" className={styles.control} size={48} />
            <IconButton icon="volume" label={muted ? "Unmute (m)" : "Mute (m)"} onClick={() => setMuted(!muted)} className={styles.control} size={48} />
            <span className={styles.time}>
              {formatDuration(time)} / {formatDuration(duration)}
            </span>
            {current.title && (
              <button type="button" className={styles.chapter}>
                <span className={styles.chapterDot}>•</span> {current.title} <Icon name="chevronRight" size={18} />
              </button>
            )}
          </div>
          <div className={styles.right}>
            {video.badges.includes("CC") && <IconButton icon="captions" label="Subtitles/closed captions (c)" aria-pressed={captions} onClick={() => setCaptions(!captions)} className={cx(styles.control, captions && styles.on)} size={48} />}
            <span className={styles.settings}>
              <IconButton icon="settings" label="Settings" className={styles.control} size={48} />
              {video.badges.includes("4K") && <span className={styles.hd}>4K</span>}
            </span>
            <IconButton icon="miniplayer" label="Miniplayer (i)" className={styles.control} size={48} />
            <IconButton icon="theater" label="Theater mode (t)" className={styles.control} size={48} />
            <IconButton icon="fullscreen" label="Full screen (f)" className={styles.control} size={48} />
          </div>
        </div>
      </div>
    </div>
  );
}
