import { keepPreviousData, useInfiniteQuery, useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { NavLink, useParams } from "react-router";
import { channelQuery, channelVideosQuery } from "../../api/queries";
import type { ChannelVideoSort } from "../../api/types";
import { ChipBar } from "../../components/ChipBar";
import { IconButton } from "../../components/Button";
import { cx } from "../../lib/cx";
import { useDocumentTitle } from "../../lib/hooks";
import { navigationDuration } from "../../lib/navigation";
import { flush, log } from "../../lib/telemetry";
import { emit } from "../../lib/workload";
import { ChannelHeader } from "./ChannelHeader";
import { GridVideo } from "./GridVideo";
import styles from "./ChannelPage.module.css";

const SORTS: { id: ChannelVideoSort; label: string }[] = [
  { id: "latest", label: "Latest" },
  { id: "popular", label: "Popular" },
  { id: "oldest", label: "Oldest" },
];

export function handleOf(param: string | undefined): string {
  return param?.startsWith("@") ? param.slice(1) : "";
}

export function ChannelPage() {
  const params = useParams();
  const handle = handleOf(params.handle);
  const tab = params.tab ?? "home";
  const { data } = useQuery(channelQuery(handle));
  const channel = data!.channel;
  const [sort, setSort] = useState<ChannelVideoSort>("latest");
  const videos = useInfiniteQuery({ ...channelVideosQuery(handle, sort), placeholderData: keepPreviousData, enabled: tab === "videos" });
  const items = videos.data?.pages.flatMap((page) => page.items) ?? [];
  const loadedSort = videos.isPlaceholderData ? null : videos.data?.pages[0].sort;
  useDocumentTitle(channel.name);

  useEffect(() => {
    log({ type: "page_view", page: "channel", path: `/@${handle}/${tab}`, durationMs: navigationDuration() });
    flush();
    emit("page-rendered", { page: "channel", handle, tab });
  }, [handle, tab]);

  useEffect(() => {
    if (!loadedSort || loadedSort === "latest") return;
    flush();
    emit("channel-videos-rendered", { handle, sort: loadedSort });
  }, [handle, loadedSort]);

  return (
    <div className={styles.page} data-page="channel">
      <ChannelHeader channel={channel} />
      <nav className={styles.tabs} aria-label="Channel tabs">
        {channel.tabs.map((name) => (
          <NavLink key={name} to={`/@${handle}/${name.toLowerCase()}`} className={({ isActive }) => cx(styles.tab, isActive && styles.active)} data-tab={name.toLowerCase()}>
            {name}
          </NavLink>
        ))}
        <IconButton icon="search" label="Search this channel" />
      </nav>
      {tab === "videos" ? (
        <>
          <ChipBar chips={SORTS} selected={sort} onSelect={(id) => setSort(id as ChannelVideoSort)} label="Sort videos" />
          <div className={styles.grid} aria-busy={videos.isPlaceholderData}>
            {items.map((video, i) => (
              <GridVideo key={video.id} video={video} position={i} surface="channel-videos" />
            ))}
          </div>
        </>
      ) : (
        <p className={styles.empty}>This tab isn't part of the journey; the Videos tab is.</p>
      )}
    </div>
  );
}
