import { useLayoutEffect, useRef, useState } from "react";
import { cx } from "../lib/cx";
import { IconButton } from "./Button";
import styles from "./ChipBar.module.css";

export interface ChipItem {
  id: string;
  label: string;
}

/**
 * A row of filter chips that scrolls horizontally, with arrow buttons where
 * it overflows. The overflow is read from the layout after each render.
 */
export function ChipBar({ chips, selected, onSelect, label, className }: { chips: ChipItem[]; selected: string; onSelect: (id: string) => void; label: string; className?: string }) {
  const scroller = useRef<HTMLDivElement>(null);
  const [overflow, setOverflow] = useState({ start: false, end: false });

  const measure = () => {
    const element = scroller.current;
    if (!element) return;
    const start = element.scrollLeft > 0;
    const end = element.scrollLeft + element.clientWidth < element.scrollWidth - 1;
    setOverflow((current) => (current.start === start && current.end === end ? current : { start, end }));
  };

  useLayoutEffect(measure, [chips]);

  const scrollBy = (direction: number) => {
    const element = scroller.current;
    if (element) element.scrollBy({ left: direction * element.clientWidth * 0.8 });
  };

  return (
    <div className={cx(styles.bar, className)}>
      {overflow.start && (
        <div className={cx(styles.arrow, styles.left)}>
          <IconButton icon="chevronLeft" label="Previous" onClick={() => scrollBy(-1)} />
        </div>
      )}
      <div className={styles.scroller} ref={scroller} onScroll={measure} role="tablist" aria-label={label}>
        {chips.map((chip) => (
          <button
            key={chip.id}
            type="button"
            role="tab"
            aria-selected={chip.id === selected}
            className={cx(styles.chip, chip.id === selected && styles.selected)}
            onClick={() => onSelect(chip.id)}
            data-chip={chip.id}
          >
            {chip.label}
          </button>
        ))}
      </div>
      {overflow.end && (
        <div className={cx(styles.arrow, styles.right)}>
          <IconButton icon="chevronRight" label="Next" onClick={() => scrollBy(1)} />
        </div>
      )}
    </div>
  );
}
