import { QueryClientProvider } from "@tanstack/react-query";
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { RouterProvider } from "react-router";
import { apiGet } from "./api/client";
import { preloadResponses } from "./api/network";
import { queryClient } from "./app/queryClient";
import { createRouter } from "./app/router";
import { setNow } from "./lib/clock";
import { flushDebounced } from "./lib/debounce";
import { markNavigationStart } from "./lib/navigation";
import { startSession } from "./lib/telemetry";
import { benchmarkMode, nextEvent } from "./lib/workload";
import "./styles/theme.css";
import "./styles/global.css";

declare global {
  interface Window {
    videoWorkload: { ready: Promise<void>; nextEvent: typeof nextEvent; flushDebounced: typeof flushDebounced };
  }
}

interface PageConfig {
  now: string;
  locale: string;
  region: string;
  images: string[];
}

const preloaded: HTMLImageElement[] = [];

/**
 * In benchmark mode the images are loaded up front, like the responses, so no step waits for them.
 * An image that doesn't load (a content blocker, for one) fails the run: the steps would do less work.
 */
async function preloadImages(urls: string[]) {
  await Promise.all(
    urls.map((url) => {
      const image = new Image();
      image.src = url;
      preloaded.push(image);
      return image.decode().catch(() => {
        if (!image.naturalWidth) throw new Error(`Couldn't load ${image.src}; a content blocker may have blocked it`);
      });
    }),
  );
}

async function start() {
  startSession();
  await preloadResponses(document.baseURI);
  const config = await apiGet<PageConfig>("config");
  setNow(config.now);
  if (benchmarkMode) await preloadImages(config.images);
  const router = createRouter();
  router.subscribe((state) => {
    if (state.navigation.state === "loading") markNavigationStart();
  });
  const rendered = nextEvent("page-rendered");
  createRoot(document.getElementById("root")!).render(
    <StrictMode>
      <QueryClientProvider client={queryClient}>
        <RouterProvider router={router} />
      </QueryClientProvider>
    </StrictMode>,
  );
  await rendered;
}

window.videoWorkload = { ready: start(), nextEvent, flushDebounced };
