// Splits user text (descriptions, comments) into the parts the UI links:
// URLs, hashtags, @mentions and timestamps.
export type Segment =
  | { type: "text"; text: string }
  | { type: "url"; text: string; href: string }
  | { type: "hashtag"; text: string; tag: string }
  | { type: "mention"; text: string; handle: string }
  | { type: "timestamp"; text: string; seconds: number };

const TOKEN = /(https?:\/\/[^\s]+)|(#[\p{L}\p{N}_]+)|(@[A-Za-z0-9_.-]+)|(\b\d{1,2}:\d{2}(?::\d{2})?\b)/gu;

function toSeconds(text: string): number {
  return text.split(":").reduce((total, part) => total * 60 + Number(part), 0);
}

export function parseLine(line: string): Segment[] {
  const segments: Segment[] = [];
  let last = 0;
  for (const match of line.matchAll(TOKEN)) {
    const index = match.index ?? 0;
    if (index > last) segments.push({ type: "text", text: line.slice(last, index) });
    const [text, url, hashtag, mention, timestamp] = match;
    if (url) segments.push({ type: "url", text: url.replace(/^https?:\/\//, "").replace(/\/$/, ""), href: url });
    else if (hashtag) segments.push({ type: "hashtag", text: hashtag, tag: hashtag.slice(1) });
    else if (mention) segments.push({ type: "mention", text: mention, handle: mention.slice(1) });
    else if (timestamp) segments.push({ type: "timestamp", text: timestamp, seconds: toSeconds(timestamp) });
    last = index + text.length;
  }
  if (last < line.length) segments.push({ type: "text", text: line.slice(last) });
  return segments;
}

export function parseText(text: string): Segment[][] {
  return text.split("\n").map(parseLine);
}

/** Splits `text` around the words of `query`, for highlighting matches. */
export function highlight(text: string, query: string): { text: string; match: boolean }[] {
  const words = query
    .toLowerCase()
    .split(/\s+/)
    .filter((word) => word.length > 1)
    .map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (!words.length) return [{ text, match: false }];
  const pattern = new RegExp(`(${words.join("|")})`, "giu");
  return text
    .split(pattern)
    .map((part, i) => ({ text: part, match: i % 2 === 1 }))
    .filter((part) => part.text);
}
