import type { Badge, VideoSummary } from "../api/types";
import { cx } from "../lib/cx";
import { durationLabel, formatDuration } from "../lib/format";
import { Icon } from "./Icon";
import styles from "./Thumbnail.module.css";

const BADGE_LABELS: Record<Badge, string> = { "4K": "4K", CC: "CC", HDR: "HDR", MEMBERS: "Members only" };

export function badgeLabel(badge: Badge): string {
  return BADGE_LABELS[badge];
}

/** A video's thumbnail with its duration or live label and watch progress. */
export function Thumbnail({ video, width, progress = 0, className, size = "m" }: { video: VideoSummary; width: number; progress?: number; className?: string; size?: "s" | "m" | "l" }) {
  const height = Math.round((width * 9) / 16);
  return (
    <div className={cx(styles.thumbnail, styles[size], className)}>
      <img src={video.thumbnail} width={width} height={height} alt="" decoding="async" />
      <div className={styles.overlays}>
        {video.live ? (
          <span className={cx(styles.time, styles.live)}>
            <Icon name="live" size={14} />
            LIVE
          </span>
        ) : (
          <span className={styles.time} aria-label={durationLabel(video.durationSeconds)}>
            {formatDuration(video.durationSeconds)}
          </span>
        )}
        {video.badges.includes("MEMBERS") && <span className={styles.members}>Members only</span>}
      </div>
      {progress > 0 && (
        <div className={styles.progress} role="progressbar" aria-valuenow={Math.round(progress * 100)} aria-valuemin={0} aria-valuemax={100} aria-label="Watched">
          <div className={styles.progressFill} style={{ width: `${progress * 100}%` }} />
        </div>
      )}
      <div className={styles.hoverActions} aria-hidden="true">
        <span className={styles.hoverAction}>
          <Icon name="clock" size={18} />
        </span>
        <span className={styles.hoverAction}>
          <Icon name="playlist" size={18} />
        </span>
      </div>
    </div>
  );
}
