import { keepPreviousData, useInfiniteQuery } from "@tanstack/react-query";
import { useEffect, useRef, useState } from "react";
import { commentsQuery } from "../../api/queries";
import type { CommentSort } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { Button } from "../../components/Button";
import { Menu } from "../../components/Menu";
import { Spinner } from "../../components/Spinner";
import { formatCount, pluralize } from "../../lib/format";
import { useNearViewport } from "../../lib/hooks";
import { flush, log } from "../../lib/telemetry";
import { emit } from "../../lib/workload";
import { CommentThread } from "./CommentThread";
import styles from "./CommentsSection.module.css";

const SORTS = [
  { value: "top" as const, label: "Top comments" },
  { value: "newest" as const, label: "Newest first" },
];

/** Comments load when the section comes near the viewport. */
export function CommentsSection({ videoId, commentCount, channelHandle, onSeek }: { videoId: string; commentCount: number; channelHandle: string; onSeek: (seconds: number) => void }) {
  const section = useRef<HTMLElement>(null);
  const [reached, setReached] = useState(false);
  const [sort, setSort] = useState<CommentSort>("top");
  useNearViewport(section, () => setReached(true), { enabled: !reached, margin: -100 });
  const { data, isPending, isError, isPlaceholderData, fetchNextPage, hasNextPage, isFetchingNextPage } = useInfiniteQuery({
    ...commentsQuery(videoId, sort),
    enabled: reached,
    placeholderData: keepPreviousData,
  });
  const threads = data?.pages.flatMap((page) => page.threads) ?? [];
  const pageCount = data?.pages.length ?? 0;

  useEffect(() => {
    if (!pageCount || isPlaceholderData) return;
    flush();
    emit("comments-rendered", { videoId, sort, pages: pageCount });
  }, [videoId, sort, pageCount, isPlaceholderData]);

  return (
    <section ref={section} id="comments" className={styles.comments} aria-label="Comments">
      <header className={styles.header}>
        <h2 className={styles.count}>{pluralize(data?.pages[0].totalCount ?? commentCount, "Comment", "Comments")}</h2>
        <Menu
          label="Sort comments"
          items={SORTS}
          selected={sort}
          onSelect={(value) => {
            setSort(value);
            log({ type: "interaction", name: "sort_comments", detail: value });
          }}
          trigger={({ open, toggle, id }) => (
            <Button variant="text" icon="sort" aria-haspopup="menu" aria-expanded={open} aria-controls={id} onClick={toggle} data-comments-sort="">
              Sort by
            </Button>
          )}
        />
      </header>
      <div className={styles.compose}>
        <Avatar src="img/avatar/39.png" size={40} />
        <button type="button" className={styles.placeholder}>
          Add a comment...
        </button>
      </div>
      {reached && isPending && <Spinner label="Loading comments" />}
      {isError && <p role="alert">Comments couldn't be loaded.</p>}
      <div className={styles.threads} aria-busy={isPlaceholderData}>
        {threads.map((comment, i) => (
          <CommentThread key={comment.id} comment={comment} position={i} channelHandle={channelHandle} onSeek={onSeek} />
        ))}
      </div>
      {pageCount > 0 && hasNextPage && (
        <div className={styles.more}>
          {isFetchingNextPage ? (
            <Spinner label="Loading more comments" />
          ) : (
            <Button variant="outline" onClick={() => void fetchNextPage()}>
              Show more comments ({formatCount(Math.max(0, (data?.pages[0].totalCount ?? 0) - threads.length))} left)
            </Button>
          )}
        </div>
      )}
    </section>
  );
}
