import { useState } from "react";
import type { VideoDetail } from "../../api/types";
import { Button } from "../../components/Button";
import { Icon } from "../../components/Icon";
import { cx } from "../../lib/cx";
import { formatCompact, formatCount } from "../../lib/format";
import { log } from "../../lib/telemetry";
import styles from "./VideoActions.module.css";

type Rating = "like" | "dislike" | null;

export function VideoActions({ video }: { video: VideoDetail }) {
  const [rating, setRating] = useState<Rating>(null);
  const [saved, setSaved] = useState(false);
  const likes = video.likeCount + (rating === "like" ? 1 : 0);
  const rate = (next: Rating) => {
    const value = rating === next ? null : next;
    setRating(value);
    log({ type: "interaction", name: value ?? "unrate", detail: video.id });
  };
  return (
    <div className={styles.actions}>
      <div className={styles.segmented} role="group" aria-label="Rate this video">
        <button
          type="button"
          className={cx(styles.segment, rating === "like" && styles.pressed)}
          aria-pressed={rating === "like"}
          aria-label={`Like this video along with ${formatCount(likes)} other people`}
          onClick={() => rate("like")}
        >
          <Icon name="like" />
          <span>{formatCompact(likes)}</span>
        </button>
        <span className={styles.divider} />
        <button type="button" className={cx(styles.segment, rating === "dislike" && styles.pressed)} aria-pressed={rating === "dislike"} aria-label="Dislike this video" onClick={() => rate("dislike")}>
          <Icon name="dislike" />
        </button>
      </div>
      <Button icon="share">Share</Button>
      <Button icon="download">Download</Button>
      <Button icon="save" aria-pressed={saved} onClick={() => setSaved(!saved)}>
        {saved ? "Saved" : "Save"}
      </Button>
      <Button icon="moreHorizontal" aria-label="More actions" />
    </div>
  );
}
