import { useQuery } from "@tanstack/react-query";
import { useLayoutEffect, useState } from "react";
import { Outlet, useLocation, useMatches } from "react-router";
import { homeQuery } from "../api/queries";
import { Guide } from "../features/guide/Guide";
import { Masthead } from "../features/masthead/Masthead";
import styles from "./AppLayout.module.css";

/** What shows while the first page's data loads. */
export function AppShellFallback() {
  return <div className={styles.app} aria-busy="true" />;
}

/** Pages that set `handle: { guide: false }` show no guide, as the watch page does. */
export function AppLayout() {
  const location = useLocation();
  const matches = useMatches();
  const [collapsed, setCollapsed] = useState(false);
  const showGuide = !matches.some((match) => (match.handle as { guide?: boolean } | undefined)?.guide === false);
  const { data: home } = useQuery(homeQuery());

  useLayoutEffect(() => {
    window.scrollTo(0, 0);
  }, [location.pathname, location.search]);

  return (
    <div className={styles.app}>
      <a className={styles.skip} href="#content">
        Skip navigation
      </a>
      <Masthead onToggleGuide={() => setCollapsed(!collapsed)} />
      <div className={styles.body}>
        {showGuide && <Guide mini={collapsed} subscriptions={home?.subscriptions ?? []} />}
        <main id="content" className={styles.content}>
          <Outlet />
        </main>
      </div>
    </div>
  );
}
