import { useRef, useState } from "react";
import { Link } from "react-router";
import type { Comment } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { Button } from "../../components/Button";
import { Icon } from "../../components/Icon";
import { RichText } from "../../components/RichText";
import { cx } from "../../lib/cx";
import { formatCompact, formatRelative, pluralize } from "../../lib/format";
import { useIsTruncated } from "../../lib/hooks";
import { log, useImpression } from "../../lib/telemetry";
import styles from "./CommentThread.module.css";

export function CommentThread({ comment, position, channelHandle, onSeek }: { comment: Comment; position: number; channelHandle: string; onSeek: (seconds: number) => void }) {
  useImpression("watch-comments", "comment", comment.id, position);
  const [expanded, setExpanded] = useState(false);
  const [liked, setLiked] = useState(false);
  const [repliesOpen, setRepliesOpen] = useState(false);
  const text = useRef<HTMLDivElement>(null);
  const truncated = useIsTruncated(text, [comment.id]);
  const { author } = comment;
  const likes = comment.likeCount + (liked ? 1 : 0);

  return (
    <article className={styles.thread} aria-labelledby={`comment-${comment.id}`} data-comment="">
      <Link to={`/@${author.handle}/videos`} tabIndex={-1} aria-hidden="true">
        <Avatar src={author.avatar} size={40} />
      </Link>
      <div className={styles.main}>
        {comment.pinned && (
          <p className={styles.pinned}>
            <Icon name="pin" size={16} /> Pinned by @{channelHandle}
          </p>
        )}
        <header className={styles.header} id={`comment-${comment.id}`}>
          <Link to={`/@${author.handle}/videos`} className={cx(styles.author, author.isCreator && styles.creator)}>
            @{author.handle}
            {author.verified && <Icon name="check" size={14} label="Verified" />}
          </Link>
          <span className={styles.time}>
            {formatRelative(comment.publishedAt)}
            {comment.edited && " (edited)"}
          </span>
        </header>
        <div ref={text} className={cx(styles.text, !expanded && styles.clamped)}>
          <RichText text={comment.text} onSeek={onSeek} />
        </div>
        {(truncated || expanded) && (
          <button type="button" className={styles.readMore} onClick={() => setExpanded(!expanded)}>
            {expanded ? "Show less" : "Read more"}
          </button>
        )}
        <div className={styles.toolbar}>
          <button
            type="button"
            className={cx(styles.tool, liked && styles.pressed)}
            aria-pressed={liked}
            aria-label={`Like this comment along with ${pluralize(likes, "other person", "other people")}`}
            onClick={() => {
              setLiked(!liked);
              log({ type: "interaction", name: "like_comment", detail: comment.id });
            }}
          >
            <Icon name="like" size={18} />
          </button>
          {likes > 0 && <span className={styles.likes}>{formatCompact(likes)}</span>}
          <button type="button" className={styles.tool} aria-label="Dislike this comment">
            <Icon name="dislike" size={18} />
          </button>
          {comment.hearted && (
            <span className={styles.heart} title={`Loved by @${channelHandle}`}>
              <Icon name="heart" size={14} label={`Loved by @${channelHandle}`} />
            </span>
          )}
          <Button variant="text" size="s">
            Reply
          </Button>
        </div>
        {comment.replyCount > 0 && (
          <Button variant="text" icon="chevronDown" className={styles.replies} aria-expanded={repliesOpen} onClick={() => setRepliesOpen(!repliesOpen)}>
            {pluralize(comment.replyCount, "reply", "replies")}
          </Button>
        )}
        {repliesOpen && <p className={styles.repliesEmpty}>Replies aren't part of this journey.</p>}
      </div>
      <button type="button" className={styles.menu} aria-label="Action menu">
        <Icon name="more" size={20} />
      </button>
    </article>
  );
}
