import { useRef, useState } from "react";
import type { ChannelDetail } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { Button } from "../../components/Button";
import { Icon } from "../../components/Icon";
import { SubscribeButton } from "../../components/SubscribeButton";
import { cx } from "../../lib/cx";
import { formatDate, formatSubscribers, pluralize } from "../../lib/format";
import { useIsTruncated } from "../../lib/hooks";
import styles from "./ChannelHeader.module.css";

export function ChannelHeader({ channel }: { channel: ChannelDetail }) {
  const [aboutOpen, setAboutOpen] = useState(false);
  const description = useRef<HTMLParagraphElement>(null);
  const truncated = useIsTruncated(description, [channel.id]);
  const [first, ...more] = channel.links;
  return (
    <header className={styles.header}>
      <img className={styles.banner} src={channel.banner} width={1060} height={176} alt="" decoding="async" />
      <div className={styles.row}>
        <Avatar src={channel.avatar} size={160} alt={channel.name} />
        <div className={styles.info}>
          <h1 className={styles.name}>
            {channel.name}
            {channel.verified && <Icon name="check" size={20} label="Verified" className={styles.verified} />}
          </h1>
          <p className={styles.meta}>
            <b>@{channel.handle}</b>
            <span aria-hidden="true"> • </span>
            {formatSubscribers(channel.subscriberCount)}
            <span aria-hidden="true"> • </span>
            {pluralize(channel.videoCount, "video", "videos")}
          </p>
          <div className={styles.descriptionRow}>
            <p ref={description} className={cx(styles.description, !aboutOpen && styles.clamped)}>
              {channel.description}
            </p>
            {(truncated || aboutOpen) && (
              <button type="button" className={styles.more} onClick={() => setAboutOpen(!aboutOpen)} aria-expanded={aboutOpen}>
                {aboutOpen ? "less" : "...more"}
              </button>
            )}
          </div>
          {first && (
            <p className={styles.links}>
              <a href={first.url} target="_blank" rel="noopener noreferrer">
                {new URL(first.url).host + new URL(first.url).pathname}
              </a>
              {more.length > 0 && <span> and {pluralize(more.length, "more link", "more links")}</span>}
            </p>
          )}
          {aboutOpen && (
            <dl className={styles.about}>
              <dt>Joined</dt>
              <dd>{formatDate(channel.joinedAt)}</dd>
              <dt>Location</dt>
              <dd>{channel.country}</dd>
            </dl>
          )}
          <div className={styles.actions}>
            <SubscribeButton channelId={channel.id} channelName={channel.name} />
            <Button variant="tonal">Join</Button>
          </div>
        </div>
      </div>
    </header>
  );
}
