import { useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";

/**
 * Calls `onNear` when the element comes within `margin` pixels of the
 * viewport's bottom while the user scrolls: infinite lists and lazily loaded
 * sections. The position is checked in the scroll handler itself.
 */
export function useNearViewport(ref: RefObject<HTMLElement | null>, onNear: () => void, { enabled = true, margin = 600 } = {}) {
  const callback = useRef(onNear);
  useEffect(() => {
    callback.current = onNear;
  });
  useEffect(() => {
    if (!enabled) return;
    const check = () => {
      const element = ref.current;
      if (element && element.getBoundingClientRect().top < window.innerHeight + margin) callback.current();
    };
    window.addEventListener("scroll", check, { passive: true });
    window.addEventListener("resize", check);
    return () => {
      window.removeEventListener("scroll", check);
      window.removeEventListener("resize", check);
    };
  }, [ref, enabled, margin]);
}

/** Whether a line-clamped or height-limited element hides some of its content. */
export function useIsTruncated(ref: RefObject<HTMLElement | null>, deps: unknown[]) {
  const [truncated, setTruncated] = useState(false);
  useLayoutEffect(() => {
    const element = ref.current;
    if (element) setTruncated(element.scrollHeight > element.clientHeight + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
  return truncated;
}

export function useDocumentTitle(title: string) {
  useEffect(() => {
    document.title = `${title} - Clipwell`;
  }, [title]);
}
