import { useQuery } from "@tanstack/react-query";
import { useEffect } from "react";
import { Link } from "react-router";
import { homeQuery } from "../../api/queries";
import { Avatar } from "../../components/Avatar";
import { ChannelName, channelPath } from "../../components/ChannelName";
import { useDocumentTitle } from "../../lib/hooks";
import { navigationDuration } from "../../lib/navigation";
import { flush, log } from "../../lib/telemetry";
import { emit } from "../../lib/workload";
import { GridVideo } from "../channel/GridVideo";
import styles from "./HomePage.module.css";

export function HomePage() {
  const { data } = useQuery(homeQuery());
  useDocumentTitle("Home");

  useEffect(() => {
    log({ type: "page_view", page: "home", path: "/", durationMs: navigationDuration() });
    flush();
    emit("page-rendered", { page: "home" });
  }, []);

  return (
    <div className={styles.page} data-page="home">
      <h2 className="visually-hidden">Recommended</h2>
      <div className={styles.grid}>
        {data?.items.map((video, i) => (
          <GridVideo key={video.id} video={video} position={i} surface="home">
            <Link to={channelPath(video.channel)} tabIndex={-1} aria-hidden="true">
              <Avatar src={video.channel.avatar} size={36} />
            </Link>
          </GridVideo>
        ))}
      </div>
      {data && (
        <p className={styles.channels}>
          From{" "}
          {data.items.slice(0, 3).map((video) => (
            <span key={video.id}>
              <ChannelName channel={video.channel} surface="home" />{" "}
            </span>
          ))}
        </p>
      )}
    </div>
  );
}
