import type { ReactNode } from "react";
import { Link } from "react-router";
import type { VideoSummary } from "../../api/types";
import { IconButton } from "../../components/Button";
import { Thumbnail } from "../../components/Thumbnail";
import { VideoMeta } from "../../components/VideoMeta";
import { logClick, useImpression } from "../../lib/telemetry";
import { videoLabel, videoPath } from "../search/VideoResult";
import styles from "./GridVideo.module.css";

/** A video in a grid: the channel's videos tab and the home page. */
export function GridVideo({ video, position, surface, children }: { video: VideoSummary; position: number; surface: string; children?: ReactNode }) {
  useImpression(surface, "video", video.id, position);
  const onClick = () => logClick(surface, "video", video.id, position);
  return (
    <article className={styles.item} data-grid-video="">
      <Link to={videoPath(video.id)} onClick={onClick} tabIndex={-1} aria-hidden="true">
        <Thumbnail video={video} width={320} />
      </Link>
      <div className={styles.details}>
        {children}
        <div className={styles.text}>
          <h3 className={styles.title}>
            <Link to={videoPath(video.id)} onClick={onClick} aria-label={videoLabel(video)} title={video.title}>
              {video.title}
            </Link>
          </h3>
          <VideoMeta video={video} />
        </div>
        <IconButton icon="more" label="Action menu" size={36} className={styles.menu} />
      </div>
    </article>
  );
}
