import { NavLink } from "react-router";
import type { HomeResponse } from "../../api/types";
import { Avatar } from "../../components/Avatar";
import { channelPath } from "../../components/ChannelName";
import { Icon, type IconName } from "../../components/Icon";
import { cx } from "../../lib/cx";
import styles from "./Guide.module.css";

interface Entry {
  label: string;
  icon: IconName;
  to: string;
}

const MAIN: Entry[] = [
  { label: "Home", icon: "home", to: "/" },
  { label: "Shorts", icon: "shorts", to: "/shorts" },
  { label: "Subscriptions", icon: "subscriptions", to: "/feed/subscriptions" },
];

const YOU: Entry[] = [
  { label: "History", icon: "history", to: "/feed/history" },
  { label: "Playlists", icon: "playlist", to: "/feed/playlists" },
  { label: "Watch later", icon: "clock", to: "/playlist?list=WL" },
  { label: "Liked videos", icon: "like", to: "/playlist?list=LL" },
];

const EXPLORE: Entry[] = [
  { label: "Trending", icon: "trending", to: "/feed/trending" },
  { label: "Music", icon: "music", to: "/channel/music" },
  { label: "Gaming", icon: "gaming", to: "/gaming" },
  { label: "News", icon: "news", to: "/channel/news" },
  { label: "Learning", icon: "learning", to: "/channel/learning" },
];

const FOOTER = ["About", "Press", "Copyright", "Contact us", "Creators", "Advertise", "Developers", "Terms", "Privacy", "Policy & Safety", "How Clipwell works", "Test new features"];

function GuideEntry({ entry, mini }: { entry: Entry; mini: boolean }) {
  return (
    <li>
      <NavLink to={entry.to} end className={({ isActive }) => cx(styles.entry, mini && styles.miniEntry, isActive && styles.active)} title={entry.label}>
        <Icon name={entry.icon} />
        <span className={styles.label}>{entry.label}</span>
      </NavLink>
    </li>
  );
}

export function Guide({ mini, subscriptions }: { mini: boolean; subscriptions: HomeResponse["subscriptions"] }) {
  if (mini) {
    return (
      <nav className={cx(styles.guide, styles.mini)} aria-label="Guide">
        <ul className={styles.section}>
          {[...MAIN, { label: "You", icon: "user" as const, to: "/feed/you" }].map((entry) => (
            <GuideEntry key={entry.label} entry={entry} mini />
          ))}
        </ul>
      </nav>
    );
  }
  return (
    <nav className={styles.guide} aria-label="Guide">
      <ul className={styles.section}>
        {MAIN.map((entry) => (
          <GuideEntry key={entry.label} entry={entry} mini={false} />
        ))}
      </ul>
      <section className={styles.section} aria-labelledby="guide-you">
        <h2 id="guide-you" className={styles.heading}>
          You <Icon name="chevronRight" size={16} />
        </h2>
        <ul>
          {YOU.map((entry) => (
            <GuideEntry key={entry.label} entry={entry} mini={false} />
          ))}
        </ul>
      </section>
      <section className={styles.section} aria-labelledby="guide-subscriptions">
        <h2 id="guide-subscriptions" className={styles.heading}>
          Subscriptions
        </h2>
        <ul>
          {subscriptions.map((channel) => (
            <li key={channel.id}>
              <NavLink to={channelPath(channel)} className={({ isActive }) => cx(styles.entry, isActive && styles.active)} title={channel.name}>
                <Avatar src={channel.avatar} size={24} />
                <span className={styles.label}>{channel.name}</span>
                {channel.live ? <Icon name="live" size={18} className={styles.liveDot} label="Live" /> : channel.hasNewVideos && <span className={styles.newDot} aria-label="New videos" />}
              </NavLink>
            </li>
          ))}
        </ul>
      </section>
      <section className={styles.section} aria-labelledby="guide-explore">
        <h2 id="guide-explore" className={styles.heading}>
          Explore
        </h2>
        <ul>
          {EXPLORE.map((entry) => (
            <GuideEntry key={entry.label} entry={entry} mini={false} />
          ))}
        </ul>
      </section>
      <footer className={styles.footer}>
        {FOOTER.map((label) => (
          <a key={label} href={`#${label.toLowerCase().replace(/[^a-z]+/g, "-")}`}>
            {label}
          </a>
        ))}
        <p>© 2026 Clipwell</p>
      </footer>
    </nav>
  );
}
