// First-party ads: the ad server's response is part of the page's response,
// and the page reports the impression itself, with the ad's tracking id and
// a pixel URL for the ads backend.
import { useEffect } from "react";
import type { Ad } from "../../api/types";
import { log } from "../../lib/telemetry";

let impressionCount = 0;

function pixelUrl(ad: Ad, slot: string): string {
  const params = new URLSearchParams({ ai: ad.trackingId, slot, fmt: ad.format, adv: ad.advertiser, n: String(++impressionCount) });
  return `/pagead/view?${params}`;
}

export function useAdImpression(ad: Ad, slot: string) {
  useEffect(() => {
    log({ type: "ad_impression", slot, adId: ad.id, trackingId: ad.trackingId, pixel: pixelUrl(ad, slot) });
  }, [ad, slot]);
}

export function adClickUrl(ad: Ad, slot: string): string {
  const url = new URL(ad.clickUrl);
  url.searchParams.set("slot", slot);
  url.searchParams.set("ai", ad.trackingId);
  return url.href;
}
