// The app's side of the benchmark: tasks for the simulated network and the
// events a step awaits. A page emits its event from an effect once the
// response it asked for is committed.
import { useEffect } from "react";

export const benchmarkMode = window.top !== window || new URLSearchParams(location.search).has("benchmark");

const EVENT_PREFIX = "videosite:";

let channel: MessageChannel | null = null;
const tasks: (() => void)[] = [];

/** Runs `callback` in a task of its own, without the clamping of nested timers. */
export function afterTask(callback: () => void) {
  if (!channel) {
    channel = new MessageChannel();
    channel.port1.onmessage = () => tasks.shift()?.();
  }
  tasks.push(callback);
  channel.port2.postMessage(null);
}

export type WorkloadEvent =
  | "page-rendered"
  | "suggestions-rendered"
  | "results-appended"
  | "comments-rendered"
  | "channel-videos-rendered";

export function emit(name: WorkloadEvent, detail: Record<string, unknown> = {}) {
  window.dispatchEvent(new CustomEvent(EVENT_PREFIX + name, { detail }));
}

export function nextEvent(name: WorkloadEvent): Promise<Record<string, unknown>> {
  return new Promise((resolve) => {
    window.addEventListener(EVENT_PREFIX + name, (event) => resolve((event as CustomEvent).detail), { once: true });
  });
}

/** Emits `name` after every commit in which one of `deps` changed. */
export function useCommitEvent(name: WorkloadEvent, detail: Record<string, unknown>, deps: unknown[]) {
  useEffect(() => {
    emit(name, detail);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}
