import type { VideoSummary } from "../api/types";
import { cx } from "../lib/cx";
import { formatRelative, formatViews, formatWatching } from "../lib/format";
import styles from "./VideoMeta.module.css";

/** "1.2M views • 3 weeks ago", or the live viewer count. */
export function VideoMeta({ video, className }: { video: VideoSummary; className?: string }) {
  if (video.live) {
    return (
      <div className={cx(styles.meta, className)}>
        <span>{formatWatching(video.liveViewers ?? 0)}</span>
      </div>
    );
  }
  return (
    <div className={cx(styles.meta, className)}>
      <span>{formatViews(video.viewCount)}</span>
      <span className={styles.dot} aria-hidden="true">
        •
      </span>
      <span>{formatRelative(video.publishedAt)}</span>
    </div>
  );
}
