import { useInfiniteQuery } from "@tanstack/react-query";
import { useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router";
import { searchQuery } from "../../api/queries";
import type { SearchItem } from "../../api/types";
import { Button } from "../../components/Button";
import { ChipBar } from "../../components/ChipBar";
import { Spinner } from "../../components/Spinner";
import { useDocumentTitle, useNearViewport } from "../../lib/hooks";
import { navigationDuration } from "../../lib/navigation";
import { flush, log } from "../../lib/telemetry";
import { emit } from "../../lib/workload";
import { InFeedAd } from "../ads/InFeedAd";
import { ChannelResult } from "./ChannelResult";
import { VideoResult } from "./VideoResult";
import styles from "./SearchPage.module.css";

function itemKey(item: SearchItem): string {
  switch (item.kind) {
    case "video":
      return `v:${item.video.id}`;
    case "channel":
      return `c:${item.channel.id}`;
    case "ad":
      return `a:${item.ad.id}`;
  }
}

export function SearchPage() {
  const [params] = useSearchParams();
  const query = params.get("search_query") ?? "";
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage, isFetchNextPageError } = useInfiniteQuery(searchQuery(query));
  const [chip, setChip] = useState("chip-0");
  const sentinel = useRef<HTMLDivElement>(null);
  const pages = data?.pages ?? [];
  const pageCount = pages.length;
  useDocumentTitle(query);

  useNearViewport(sentinel, () => void fetchNextPage({ cancelRefetch: false }), { enabled: hasNextPage && !isFetchingNextPage && !isFetchNextPageError });

  useEffect(() => {
    if (!pageCount) return;
    if (pageCount === 1) {
      log({ type: "page_view", page: "search", path: `/results?search_query=${query}`, durationMs: navigationDuration() });
      flush();
      emit("page-rendered", { page: "search", query });
    } else {
      flush();
      emit("results-appended", { query, pages: pageCount });
    }
  }, [query, pageCount]);

  const chips = pages[0]?.chips ?? [];
  let position = 0;
  return (
    <div className={styles.page} data-page="search">
      <div className={styles.header}>
        <ChipBar chips={chips} selected={chip} onSelect={setChip} label="Search filters" className={styles.chips} />
        <Button variant="text" icon="sort">
          Filters
        </Button>
      </div>
      <h2 className="visually-hidden">Search results for {query}</h2>
      <div className={styles.results}>
        {pages.flatMap((page) =>
          page.items.map((item) => {
            const at = position++;
            switch (item.kind) {
              case "video":
                return <VideoResult key={itemKey(item)} video={item.video} position={at} query={query} />;
              case "channel":
                return <ChannelResult key={itemKey(item)} channel={item.channel} position={at} />;
              case "ad":
                return <InFeedAd key={itemKey(item)} ad={item.ad} position={at} />;
            }
          }),
        )}
      </div>
      <div ref={sentinel} className={styles.continuation} data-continuation="">
        {isFetchingNextPage && <Spinner label="Loading more results" />}
        {isFetchNextPageError && (
          <Button variant="outline" onClick={() => void fetchNextPage()}>
            Retry
          </Button>
        )}
        {!hasNextPage && pageCount > 0 && <p className={styles.end}>No more results</p>}
      </div>
    </div>
  );
}
