// First-party telemetry: impressions, ad impressions, clicks and page views
// are queued and sent in batches. A batch goes out when it is full and at the
// end of every page view, as one JSON POST to the logging endpoint.
import { useEffect } from "react";
import { apiPost } from "../api/client";
import { nowIso } from "./clock";

export type TelemetryEvent =
  | { type: "page_view"; page: string; path: string; durationMs: number }
  | { type: "impression"; surface: string; kind: string; id: string; position: number }
  | { type: "ad_impression"; slot: string; adId: string; trackingId: string; pixel: string }
  | { type: "click"; surface: string; target: string; id: string; position?: number }
  | { type: "search"; query: string; source: "submit" | "suggestion" }
  | { type: "suggestions_shown"; query: string; count: number }
  | { type: "interaction"; name: string; detail?: string };

const BATCH_SIZE = 25;
const CLIENT = { name: "web", version: "2026.10.20", locale: "en-US", screen: "desktop" } as const;

let queue: (TelemetryEvent & { seq: number; t: number })[] = [];
let seq = 0;
let batches = 0;
let sessionStart = 0;

export function startSession() {
  sessionStart = performance.now();
}

export function log(event: TelemetryEvent) {
  queue.push({ ...event, seq: seq++, t: Math.round(performance.now() - sessionStart) });
  if (queue.length >= BATCH_SIZE) flush();
}

export function flush() {
  if (!queue.length) return;
  const events = queue;
  queue = [];
  batches++;
  void apiPost("log_event", { client: CLIENT, batch: batches, sentAt: nowIso(), events });
}

export function useImpression(surface: string, kind: string, id: string, position: number) {
  useEffect(() => {
    log({ type: "impression", surface, kind, id, position });
  }, [surface, kind, id, position]);
}

export function logClick(surface: string, target: string, id: string, position?: number) {
  log({ type: "click", surface, target, id, position });
}

if (typeof document !== "undefined") {
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") flush();
  });
}
