import { cx } from "../lib/cx";
import styles from "./Avatar.module.css";

export function Avatar({ src, size, alt = "", live = false, className }: { src: string; size: number; alt?: string; live?: boolean; className?: string }) {
  return (
    <span className={cx(styles.avatar, live && styles.live, className)} style={{ width: size, height: size }}>
      <img src={src} width={size} height={size} alt={alt} decoding="async" />
      {live && <span className={styles.liveLabel}>LIVE</span>}
    </span>
  );
}
