import type { Ad } from "../../api/types";
import { Button, IconButton } from "../../components/Button";
import { logClick } from "../../lib/telemetry";
import { adClickUrl, useAdImpression } from "./ads";
import styles from "./CompanionAd.module.css";

/** The sponsored slot above the related videos on the watch page. */
export function CompanionAd({ ad }: { ad: Ad }) {
  const slot = "watch-companion";
  useAdImpression(ad, slot);
  const href = adClickUrl(ad, slot);
  return (
    <aside className={styles.ad} aria-label={`${ad.sponsoredLabel}: ${ad.advertiser}`} data-ad-slot={slot}>
      <a href={href} target="_blank" rel="noopener sponsored" onClick={() => logClick("watch", "ad", ad.id)}>
        <img className={styles.image} src={ad.image} width={402} height={226} alt="" decoding="async" />
      </a>
      <div className={styles.row}>
        <div className={styles.text}>
          <h3 className={styles.headline}>{ad.headline}</h3>
          <p className={styles.meta}>
            <b>{ad.sponsoredLabel}</b> · {ad.displayUrl}
          </p>
        </div>
        <IconButton icon="more" label="Ad options" size={32} />
      </div>
      <Button variant="inverse" className={styles.cta} onClick={() => window.open(href, "_blank", "noopener")}>
        {ad.cta}
      </Button>
    </aside>
  );
}
