import { createBrowserRouter, data, type LoaderFunctionArgs } from "react-router";
import { channelQuery, channelVideosQuery, homeQuery, searchQuery, watchQuery } from "../api/queries";
import { RouteError } from "../components/ErrorMessage";
import { ChannelPage, handleOf } from "../features/channel/ChannelPage";
import { HomePage } from "../features/home/HomePage";
import { SearchPage } from "../features/search/SearchPage";
import { WatchPage } from "../features/watch/WatchPage";
import { AppLayout, AppShellFallback } from "./AppLayout";
import { queryClient } from "./queryClient";

// Loaders put each page's data into the query cache before the page renders,
// so a navigation commits the finished page.
const param = (request: Request, name: string) => new URL(request.url).searchParams.get(name) ?? "";

async function layoutLoader() {
  await queryClient.ensureQueryData(homeQuery());
  return null;
}

async function searchLoader({ request }: LoaderFunctionArgs) {
  await queryClient.ensureInfiniteQueryData(searchQuery(param(request, "search_query")));
  return null;
}

async function watchLoader({ request }: LoaderFunctionArgs) {
  await queryClient.ensureQueryData(watchQuery(param(request, "v")));
  return null;
}

async function channelLoader({ params }: LoaderFunctionArgs) {
  const handle = handleOf(params.handle);
  if (!handle) throw data(null, { status: 404 });
  await Promise.all([queryClient.ensureQueryData(channelQuery(handle)), params.tab === "videos" ? queryClient.ensureInfiniteQueryData(channelVideosQuery(handle, "latest")) : null]);
  return null;
}

/** The app is served from a directory; the router's base is the directory of the page. */
function basename(): string {
  return location.pathname.replace(/\/[^/]*$/, "") || "/";
}

export function createRouter() {
  return createBrowserRouter(
    [
      {
        path: "/",
        Component: AppLayout,
        loader: layoutLoader,
        HydrateFallback: AppShellFallback,
        ErrorBoundary: RouteError,
        children: [
          { index: true, Component: HomePage },
          { path: "index.html", Component: HomePage },
          { path: "results", loader: searchLoader, Component: SearchPage, ErrorBoundary: RouteError },
          { path: "watch", loader: watchLoader, Component: WatchPage, ErrorBoundary: RouteError, handle: { guide: false } },
          { path: ":handle/:tab?", loader: channelLoader, Component: ChannelPage, ErrorBoundary: RouteError },
          { path: "*", Component: RouteError, loader: () => { throw data(null, { status: 404 }); } },
        ],
      },
    ],
    { basename: basename() },
  );
}
