import type { Ad } from "../../api/types";
import { Button, IconButton } from "../../components/Button";
import { Icon } from "../../components/Icon";
import { logClick } from "../../lib/telemetry";
import { adClickUrl, useAdImpression } from "./ads";
import styles from "./InFeedAd.module.css";

/** A sponsored card between the search results. */
export function InFeedAd({ ad, position }: { ad: Ad; position: number }) {
  const slot = `search-feed-${position}`;
  useAdImpression(ad, slot);
  const href = adClickUrl(ad, slot);
  return (
    <article className={styles.ad} aria-label={`${ad.sponsoredLabel}: ${ad.advertiser}`} data-ad-slot={slot}>
      <a href={href} target="_blank" rel="noopener sponsored" className={styles.media} onClick={() => logClick("search", "ad", ad.id, position)}>
        <img src={ad.image} width={360} height={202} alt="" decoding="async" />
      </a>
      <div className={styles.body}>
        <div className={styles.header}>
          <h3 className={styles.headline}>
            <a href={href} target="_blank" rel="noopener sponsored">
              {ad.headline}
            </a>
          </h3>
          <IconButton icon="more" label="Ad options" />
        </div>
        <p className={styles.text}>{ad.body}</p>
        <div className={styles.footer}>
          <span className={styles.sponsored}>{ad.sponsoredLabel}</span>
          <span className={styles.dot}>·</span>
          <span className={styles.url}>{ad.displayUrl}</span>
          <button type="button" className={styles.info} aria-label="Why this ad?">
            <Icon name="info" size={16} />
          </button>
        </div>
        <Button variant="inverse" size="s" className={styles.cta} onClick={() => window.open(href, "_blank", "noopener")}>
          {ad.cta}
        </Button>
      </div>
    </article>
  );
}
