// Debounced callbacks, as the search box's suggestions use them. In benchmark
// mode the timer is replaced by an explicit flush that the step triggers.
import { useCallback, useEffect, useRef } from "react";
import { benchmarkMode } from "./workload";

const waiting = new Map<object, () => void>();

export function flushDebounced() {
  const calls = [...waiting.values()];
  waiting.clear();
  for (const call of calls) call();
}

export function useDebouncedCallback<A extends unknown[]>(callback: (...args: A) => void, delay: number) {
  const latest = useRef(callback);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const key = useRef({});
  useEffect(() => {
    latest.current = callback;
  });
  useEffect(() => {
    const id = key.current;
    return () => {
      clearTimeout(timer.current);
      waiting.delete(id);
    };
  }, []);
  return useCallback(
    (...args: A) => {
      if (benchmarkMode) {
        waiting.set(key.current, () => latest.current(...args));
        return;
      }
      clearTimeout(timer.current);
      timer.current = setTimeout(() => latest.current(...args), delay);
    },
    [delay],
  );
}
