import { isRouteErrorResponse, useRouteError } from "react-router";
import { ApiError } from "../api/client";
import styles from "./ErrorMessage.module.css";

export function RouteError() {
  const error = useRouteError();
  const notFound = (error instanceof ApiError && error.status === 404) || (isRouteErrorResponse(error) && error.status === 404);
  return (
    <div className={styles.error} role="alert">
      <h2>{notFound ? "This page isn't available" : "Something went wrong"}</h2>
      <p>{notFound ? "Clipwell only has the pages of the benchmark journey. Try searching for something else." : String(error)}</p>
    </div>
  );
}
